    'data-slot': 'select-item',
    '[class]': 'classes()',
    '[attr.value]': 'zValue()',
    '[attr.data-disabled]': 'zDisabled() ? "" : null',
    '[attr.data-selected]': 'isSelected() ? "" : null',
    '[attr.aria-disabled]': 'zDisabled()',
    '[attr.aria-selected]': 'isSelected()',
