    }
  }

  private readonly onDocumentToggle = (event: Event) => {
    const isOpening = (event as Event & { newState?: string }).newState === 'open';

    if (isOpening && event.target !== this.host && this.topLayer() && toastState.toasts().length > 0) {
      this.promote();
    }
