  sidebar-11-app-sidebar.component.html,src/components/sidebar-11/sidebar-11-app-sidebar.component.html,"<z-sidebar>
  <z-sidebar-content>
    <div z-sidebar-group>
      <div z-sidebar-group-label>Changes</div>

      <div z-sidebar-group-content>
        <ul z-sidebar-menu>
          @for (item of changes; track item.file) {
            <li z-sidebar-menu-item>
              <!-- `pr-8` keeps the longer Angular paths clear of the absolutely positioned badge. -->
              <button z-sidebar-menu-button class="pr-8" [title]="item.file">
                <ng-icon name="lucideFile" />
                <span class="truncate">{{ item.file }}</span>
              </button>
              <div z-sidebar-menu-badge>{{ item.state }}</div>
            </li>
          }
        </ul>
      </div>
    </div>

    <div z-sidebar-group>
      <div z-sidebar-group-label>Files</div>

      <div z-sidebar-group-content>
        <ul z-sidebar-menu>
          @for (node of tree; track node.name) {
            <ng-container [ngTemplateOutlet]="treeNode" [ngTemplateOutletContext]="{ $implicit: node }" />
          }
        </ul>
      </div>
    </div>
  </z-sidebar-content>

  <button z-sidebar-rail aria-label="Toggle Sidebar"></button>
</z-sidebar>

<!-- Recursive template: Angular's answer to shadcn's self-referencing <Tree /> component. -->
<ng-template #treeNode let-node>
  @if (!node.children) {
    <button
      z-sidebar-menu-button
      class="data-[active=true]:bg-transparent"
      [zActive]="node.name === 'button.component.ts'"
      [title]="node.name"
    >
      <ng-icon name="lucideFile" />
      <span class="truncate">{{ node.name }}</span>
    </button>
  } @else {
    <li z-sidebar-menu-item>
      <div
        z-collapsible
        class="group/collapsible [&[data-state=open]>button>ng-icon:first-child]:rotate-90"
        [zOpen]="isOpenByDefault(node)"
