      lucideMenu,
      lucideMessageCircle,
      lucidePaintbrush,
      lucideSettings,
      lucideVideo,
    }),
  ],
  templateUrl: './sidebar-13-settings-dialog.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class Sidebar13SettingsDialogComponent {
