    {
      value: 'light',
      template: this.light(),
      ariaLabel: 'Light',
    },
    {
      value: 'normal',
      template: this.normal(),
      ariaLabel: 'Normal',
    },
    {
      value: 'medium',
      template: this.medium(),
      ariaLabel: 'Medium',
    },
    {
      value: 'bold',
      template: this.bold(),
      ariaLabel: 'Bold',
    },
  ]);

  onToggleChange(value: string | string[]) {
    let weight = '';
    if (Array.isArray(value)) {
      [weight] = value;
    } else {
      weight = value;
    }
    this.fontWeight.set(weight);
  }
}
