readonly overallProgress = Math.round(
    this.v1JourneyPhases.reduce((total, phase) => total + (phase.progress ?? 0), 0) / this.v1JourneyPhases.length,
  )

this.seoService.setDocsSeo(
      'Roadmap',
      'Zard UI shipped V1.0. See the journey that got us here, and the plan for what is next: keeping v1 stable, zard-cli create, the AI SDK, and continuous docs and bug fixes.',
      '/docs/roadmap',
      'og-roadmap.jpg',
    );

const variants: Record<RoadmapPhase['status'], RoadmapBadgeVariant> = {
      completed: 'default',
      'in-progress': 'secondary',
      ongoing: 'secondary',
      planned: 'outline',
    };

const texts: Record<RoadmapPhase['status'], string> = {
      completed: 'Completed',
      'in-progress': 'In Progress',
      ongoing: 'Ongoing',
      planned: 'Planned',
    };

const accents: Record<RoadmapPhase['status'], StatusAccent> = {
      completed: { dot: 'bg-primary text-primary-foreground', bar: 'bg-primary', percent: 'text-primary' },
      'in-progress': {
        dot: 'bg-primary/70 text-primary-foreground',
        bar: 'bg-primary/70',
        percent: 'text-primary/80',
      },
      ongoing: { dot: 'bg-primary/70 text-primary-foreground', bar: 'bg-primary/70', percent: 'text-primary/80' },
      planned: { dot: 'bg-muted text-muted-foreground', bar: 'bg-muted', percent: 'text-muted-foreground' },
    };

const translations: ZardRtlTranslations<{
  title: string;
  description: string;
  body: string;
  action: string;
  cancel: string;
}> = {
  en: {
    dir: 'ltr',
    values: {
      title: 'Welcome back',
      description: 'Text, spacing and icons follow the reading direction.',
      body: 'Switch the language above to watch the card mirror with no extra code.',
      action: 'Continue',
      cancel: 'Cancel',
    },
  },
  ar: {
    dir: 'rtl',
    values: {
      title: 'مرحبا بعودتك',
      description: 'يتبع النص والمسافات والأيقونات اتجاه القراءة.',
      body: 'غيّر اللغة من الأعلى لترى البطاقة تنعكس دون أي شيفرة إضافية.',
      action: 'متابعة',
      cancel: 'إلغاء',
    },
  },
  he: {
    dir: 'rtl',
    values: {
      title: 'ברוכים השבים',
      description: 'הטקסט, הריווח והסמלים עוקבים אחרי כיוון הקריאה.',
      body: 'החליפו שפה למעלה כדי לראות את הכרטיס מתהפך ללא קוד נוסף.',
      action: 'המשך',
      cancel: 'ביטול',
    },
  },
};

readonly getStartedSteps: Step[] = [
    {
      title: 'Set the direction on the document',
      subtitle:
        'Add dir="rtl" and the language of your content to the html tag. Update lang="ar" to your target language. Every component and every overlay it opens reads the direction from there.',
      codeBlockData: HTML_DIR_BLOCK,
    },
    {
      title: 'Or scope a subtree',
      subtitle:
        'Mixed-direction page? Import the CDK Dir directive and put dir on any element. Components inside, and the overlays they open, take that direction instead of the document one.',
      codeBlockData: DIR_DIRECTIVE_BLOCK,
    },
    {
      title: 'Let the CLI do it',
      subtitle:
        'zard-cli init asks whether your app reads right to left, and --rtl / --no-rtl answer the question up front. Nothing is inferred from your project: the answer is yours.',
      codeBlockData: CLI_INIT_BLOCK,
    },
    {
