  },
  // Generated by `npm run sync:blocks` from the sibling component files — do not edit by hand.
  files: [
    {
      name: 'sidebar-09-app-sidebar.component.html',
      path: 'src/components/sidebar-09/sidebar-09-app-sidebar.component.html',
      content: `<z-sidebar zCollapsible="icon" class="overflow-hidden *:data-[sidebar=sidebar]:flex-row">
  <!-- This is the first sidebar. -->
  <!-- We disable collapsible and adjust width to icon, so it appears as icons. -->
  <z-sidebar zCollapsible="none" class="w-[calc(var(--sidebar-width-icon)+1px)]! border-r">
    <div z-sidebar-header>
      <ul z-sidebar-menu>
        <li z-sidebar-menu-item>
          <a z-sidebar-menu-button zSize="lg" href="#" class="md:h-8 md:p-0">
            <div
              class="bg-sidebar-primary text-sidebar-primary-foreground flex aspect-square size-8 items-center justify-center rounded-lg"
            >
              <ng-icon name="lucideCommand" class="size-4" />
            </div>
            <div class="grid flex-1 text-left text-sm leading-tight">
              <span class="truncate font-medium">Acme Inc</span>
              <span class="truncate text-xs">Enterprise</span>
            </div>
          </a>
        </li>
      </ul>
    </div>

    <z-sidebar-content>
      <div z-sidebar-group>
        <div z-sidebar-group-content class="px-1.5 md:px-0">
          <ul z-sidebar-menu>
            @for (item of navMain; track item.title) {
              <li z-sidebar-menu-item>
                <!-- \`hidden: false\` mirrors shadcn's \`tooltip={{ children, hidden: false }}\`: this
                     sidebar is always icon-width, so its tooltips stay on even when expanded. -->
                <button
                  z-sidebar-menu-button
                  class="px-2.5 md:px-2"
                  [zTooltip]="{ content: item.title, hidden: false }"
                  [zActive]="item.title === activeItem().title"
                  (click)="selectItem(item)"
                >
                  <ng-icon [name]="item.icon" />
                  <span>{{ item.title }}</span>
                </button>
              </li>
            }
          </ul>
        </div>
      </div>
    </z-sidebar-content>

    <div z-sidebar-footer>
      <lib-sidebar-09-nav-user [user]="user" />
    </div>
  </z-sidebar>

  <!-- This is the second sidebar. -->
  <!-- We disable collapsible and let it fill the remaining space. -->
  <z-sidebar zCollapsible="none" class="hidden flex-1 md:flex">
    <div z-sidebar-header class="gap-3.5 border-b p-4">
      <div class="flex w-full items-center justify-between">
        <div class="text-foreground text-base font-medium">{{ activeItem().title }}</div>

        <label z-field-label for="sidebar-09-unreads" class="flex items-center gap-2 text-sm">
          <span>Unreads</span>
          <z-switch zId="sidebar-09-unreads" class="shadow-none" />
        </label>
      </div>

      <input z-input z-sidebar-input placeholder="Type to search..." />
    </div>

    <z-sidebar-content>
      <div z-sidebar-group class="px-0">
        <div z-sidebar-group-content>
          @for (mail of mails(); track mail.email) {
            <a
              href="#"
              class="hover:bg-sidebar-accent hover:text-sidebar-accent-foreground flex flex-col items-start gap-2 border-b p-4 text-sm leading-tight whitespace-nowrap last:border-b-0"
            >
              <div class="flex w-full items-center gap-2">
                <span>{{ mail.name }}</span>
                <span class="ml-auto text-xs">{{ mail.date }}</span>
              </div>
              <span class="font-medium">{{ mail.subject }}</span>
              <span class="line-clamp-2 w-[260px] text-xs whitespace-break-spaces">{{ mail.teaser }}</span>
            </a>
          }
        </div>
      </div>
    </z-sidebar-content>
  </z-sidebar>
</z-sidebar>
`,
      language: 'html',
