  return buildArcLabels(names, {
    cx: width / 2,
    cy: height / 2,
    radii: names.map((_, index) => inner + band * (index + 0.5)),
    startAngle: ctx.startAngle ?? 90,
    ascending: (ctx.endAngle ?? 360) >= (ctx.startAngle ?? 90),
