readonly navSize = computed(() => {
    const size = this.zSize();
    switch (size) {
      case 'icon-xs':
        return 'xs';
      case 'icon-sm':
        return 'sm';
      case 'icon-lg':
        return 'lg';
      default:
        return 'default';
    }
  })

readonly clampedIndex = computed(() => {
    const total = Math.max(1, this.zTotal());
    return Math.min(Math.max(1, this.zPageIndex()), total);
  })

