              <span [class]="captionLabelClasses()" aria-hidden="true">
                {{ currentMonthName() }}
                <ng-icon name="lucideChevronDown" class="text-muted-foreground size-3.5!" />
              </span>
            </div>
          } @else {
            <span [class]="captionLabelClasses()">{{ longMonthName() }}</span>
          }

