  protected readonly motion = computed(() => (this.isViewportMode() ? this.service?.motion() : null));

  protected readonly classes = computed(() =>
    mergeClasses(navigationMenuContentVariants({ viewport: this.isViewportMode() }), this.class()),
  );
}
